def _validate_stored_repairs(
    document: Any,
    checkpoints: dict[str, int],
    records: list[tuple[str, dict[str, Any]]],
) -> dict[tuple[str, str], dict[str, Any]]:
    """Validate the optional ``repairExecutions`` section of a data file.

    Returns a clean ``{(peerId, ackId): binding}`` mapping of committed
    conditional repair executions. The section is optional (a version:1
    file written before the repair entries existed recovers with no
    repair bindings). When present it is a list of records, one per
    ``(peerId, ackId)`` pair, each carrying exactly ``peerId``,
    ``ackId``, ``expectedCheckpoint``, ``expectedReceipts``,
    ``suggestions``, ``results``, and ``cursor``. Because a repair
    commits its restored checkpoint atomically, every binding must name a
    registered peer whose checkpoint has reached the binding's cursor;
    the cursor may not exceed the recovered log length. Anything else is
    a corrupt file.
    """
    if "repairExecutions" not in document:
        return {}
    raw = document["repairExecutions"]
    if not isinstance(raw, list):
        raise PersistenceError("data file repairExecutions must be a list")
    repairs: dict[tuple[str, str], dict[str, Any]] = {}
    for entry in raw:
        if not isinstance(entry, dict) or set(entry.keys()) != {
            "peerId",
            "ackId",
            "expectedCheckpoint",
            "expectedReceipts",
            "suggestions",
            "results",
            "cursor",
        }:
            raise PersistenceError(
                "each repair record must be an object with peerId, ackId, "
                "expectedCheckpoint, expectedReceipts, suggestions, results, cursor"
            )
        peer_id = entry["peerId"]
        ack_id = entry["ackId"]
        expected_checkpoint = entry["expectedCheckpoint"]
        cursor = entry["cursor"]
        if not isinstance(peer_id, str) or peer_id == "":
            raise PersistenceError("repair peerId must be a non-empty string")
        if not isinstance(ack_id, str) or ack_id == "":
            raise PersistenceError("repair ackId must be a non-empty string")
        for name, value in (
            ("expectedCheckpoint", expected_checkpoint),
            ("cursor", cursor),
        ):
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                raise PersistenceError(f"repair {name} must be a non-negative integer")
        if not _is_sha256_hex64(entry["expectedReceipts"]):
            raise PersistenceError(
                "repair expectedReceipts must be 64 lowercase hexadecimal characters"
            )
        suggestions_raw = entry["suggestions"]
        if not isinstance(suggestions_raw, list) or not (
            REPAIR_BATCH_MIN <= len(suggestions_raw) <= REPAIR_BATCH_MAX
        ):
            raise PersistenceError("repair suggestions must be a list of 1-100 entries")
        suggestions = [
            _validate_stored_repair_suggestion(item) for item in suggestions_raw
        ]
        for index in range(1, len(suggestions)):
            if REPAIR_ACTIONS.index(suggestions[index]["action"]) < REPAIR_ACTIONS.index(
                suggestions[index - 1]["action"]
            ):
                raise PersistenceError("stored repair suggestions must be in processing order")
        results = _validate_stored_repair_results(
            entry["results"], [item["action"] for item in suggestions]
        )
        key = (peer_id, ack_id)
        if key in repairs:
            raise PersistenceError(f"duplicate repair binding {key!r} in data file")
        registered = checkpoints.get(peer_id)
        if registered is None or registered < cursor:
            raise PersistenceError(
                f"repair binding {key!r} names a peer whose checkpoint has not reached it"
            )
        if cursor > len(records) or cursor < expected_checkpoint:
            raise PersistenceError(
                f"repair binding {key!r} restores a cursor outside the recovered log"
            )
        repairs[key] = {
            "expectedCheckpoint": expected_checkpoint,
            "expectedReceipts": entry["expectedReceipts"],
            "suggestions": suggestions,
            "results": results,
            "cursor": cursor,
        }
    return repairs


def _is_sha256_hex64(value: Any) -> bool:
    """Return True for exactly 64 lowercase hexadecimal characters."""
    return isinstance(value, str) and len(value) == 64 and all(
        ("0" <= ch <= "9") or ("a" <= ch <= "f") for ch in value
    )


def _validate_stored_policy_events(document: Any) -> list[dict[str, Any]]:
    """Validate the optional ``policyEvents`` section of a data file.

    Returns a clean ordered list of policy-change events, each
    ``{"sequence", "digest", "tokens"}``. The section is optional (a
    version:1 file written before scope-policy change auditing existed
    simply has none, and recovers with an empty history); when present it
    must be a list whose entries carry exactly those three keys:
    ``sequence`` is a non-boolean positive integer starting at 1 and
    increasing without gaps, ``digest`` is 64 lowercase hexadecimal
    characters (the SHA-256 recorded at reload time), and ``tokens`` is a
    non-boolean non-negative integer (the reloaded policy's entry count).
    Anything else is a corrupt file.
    """
    if "policyEvents" not in document:
        return []
    raw = document["policyEvents"]
    if not isinstance(raw, list):
        raise PersistenceError("data file policyEvents must be a list")
    events: list[dict[str, Any]] = []
    for entry in raw:
        if not isinstance(entry, dict) or set(entry.keys()) != {
            "sequence",
            "digest",
            "tokens",
        }:
            raise PersistenceError(
                "each policy event must be an object with sequence, digest, tokens"
            )
        sequence = entry["sequence"]
        tokens = entry["tokens"]
        if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence < 1:
            raise PersistenceError("policy event sequence must be a positive integer")
        if sequence != len(events) + 1:
            raise PersistenceError(
                "policy event sequences must start at 1 and continue without gaps"
            )
        if not _is_sha256_hex64(entry["digest"]):
            raise PersistenceError("policy event digest must be 64 lowercase hex characters")
        if isinstance(tokens, bool) or not isinstance(tokens, int) or tokens < 0:
            raise PersistenceError("policy event tokens must be a non-negative integer")
        events.append(
            {"sequence": sequence, "digest": entry["digest"], "tokens": tokens}
        )
    return events


def _validate_stored_compensations(
    document: Any,
    identities: set[tuple[str, str]],
    transactions: dict[str, list[dict[str, Any]]],
) -> dict[str, dict[str, Any]]:
    """Validate the optional ``compensations`` section of a data file.

    Returns a clean ``{compensationId: binding}`` mapping. The section
    is optional (a version:1 file written before compensations existed
    simply has none); when present it must be a list of
    ``{"compensationId", "transactionId", "expectedPlanDigest",
    "operations", "status"}`` records with a non-empty distinct
    compensation id each, the transaction id naming a committed
    transaction, the expected plan digest being 64 lowercase
    hexadecimal characters, the entries satisfying the live
    compensation constraints with every entry identity naming an
    accepted operation (a compensation binding is committed atomically
    together with its operations), and the status being
    ``"committed"``.
    """
    if "compensations" not in document:
        return {}
    raw = document["compensations"]
    if not isinstance(raw, list):
        raise PersistenceError("data file compensations must be a list")
    compensations: dict[str, dict[str, Any]] = {}
    for record in raw:
        if not isinstance(record, dict) or set(record.keys()) != {
            "compensationId",
            "transactionId",
            "expectedPlanDigest",
            "operations",
            "status",
        }:
            raise PersistenceError(
                "each compensation record must be an object with compensationId, "
                "transactionId, expectedPlanDigest, operations, status"
            )
        compensation_id = record["compensationId"]
        transaction_id = record["transactionId"]
        if not isinstance(compensation_id, str) or compensation_id == "":
            raise PersistenceError("compensation id must be a non-empty string")
        if compensation_id in compensations:
            raise PersistenceError(
                f"duplicate compensation {compensation_id!r} in data file"
            )
        if not isinstance(transaction_id, str) or transaction_id == "":
            raise PersistenceError("compensation transactionId must be a non-empty string")
        if transaction_id not in transactions:
            raise PersistenceError(
                f"compensation {compensation_id!r} names no committed transaction "
                f"{transaction_id!r}"
            )
        expected_digest = record["expectedPlanDigest"]
        if not _is_sha256_hex64(expected_digest):
            raise PersistenceError(
                "compensation expectedPlanDigest must be 64 lowercase hex characters"
            )
        try:
            entries = _parse_compensation_entries(record["operations"])
        except ValueError as exc:
            raise PersistenceError(
                f"stored compensation violates input constraints: {exc}"
            ) from exc
        for entry in entries:
            identity = (entry["replicaId"], entry["operationId"])
            if identity not in identities:
                raise PersistenceError(
                    f"compensation {compensation_id!r} names no accepted operation "
                    f"for identity {identity!r}"
                )
        status = record["status"]
        if status != "committed":
            raise PersistenceError(f"unknown compensation status {status!r}")
        compensations[compensation_id] = {
            "transactionId": transaction_id,
            "expectedPlanDigest": expected_digest,
            "operations": entries,
            "status": status,
        }
    return compensations


